import numpy as np
def norm(cells):
    ys=[y for y,_ in cells]; xs=[x for _,x in cells]
    return frozenset((y-min(ys),x-min(xs)) for y,x in cells)
def transforms(sh):
    g=np.array([list(r) for r in sh])
    outs=set()
    for m in (g, g[:,::-1], g[::-1,:], g[::-1,::-1]):
        for _ in range(4):
            m=np.rot90(m); outs.add(tuple(map(tuple,m)))
    return outs
