def comps_of(g,bg):
    H,W=len(g),len(g[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); cl=[]
                while q:
                    y,x=q.popleft(); cl.append((y,x))
                    for dy in (-1,0,1):
                        for dx in (-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx]==g[y][x] and (ny,nx) not in seen:
                                seen.add((ny,nx)); q.append((ny,nx))
                out.append((g[r][c],set(cl)))
    return out

